                    "sql": "drop table if exists public.quickshift_mysql_shipping_factitems ; CREATE TABLE public.quickshift_mysql_shipping_factitems AS select CAST(e_order_date AS TIMESTAMP) e_order_date ,CAST(e_invoice_date AS TIMESTAMP) e_Invoice_Date ,CAST(last_modfied_date AS TIMESTAMP) last_modfied_date ,e_reference_code ,UPPER(TRIM(e_order_status)) e_order_status ,CAST(e_manifest_date AS TIMESTAMP) e_manifest_date ,facility_code ,UPPER(e_order_type) e_order_type ,UPPER(e_marketplace) e_marketplace ,UPPER(e_payment_mode) e_payment_mode ,e_order_id ,pk_order_id ,UPPER(e_company_name) e_company_name ,e_order_quantity ,md.order_sla ,CAST(md.reach_dest_date AS TIMESTAMP) reach_dest_date ,CAST(md.pickup_schedule_date AS TIMESTAMP) pickup_schedule_date ,CAST(md.attempt1_date AS TIMESTAMP) attempt1_date ,CAST(md.attempt2_date AS TIMESTAMP) attempt2_date ,CAST(md.attempt3_date AS TIMESTAMP) attempt3_date ,UPPER(bd.e_city) e_city ,UPPER(bd.e_state) e_state ,UPPER(bd.e_country) e_country ,bd.e_pin_code ,bd.e_customer_name ,UPPER(sd.e_shipping_status) e_shipping_status ,CAST(sd.s_pickup_date AS TIMESTAMP) s_pickup_date ,CAST(sd.s_delivered_date AS TIMESTAMP) s_delivered_date ,CAST(sd.s_rto_date AS TIMESTAMP) s_rto_date ,CAST(sd.s_returned_date AS TIMESTAMP) s_returned_date ,CAST(sd.s_expected_delivery_date AS TIMESTAMP) s_expected_delivery_date ,CAST(sd.s_rto_initiated_date AS TIMESTAMP) s_rto_initiated_date ,sd.e_awb_number ,UPPER(sd.e_courier) e_courier ,UPPER(opd.e_pickup_city) e_pickup_city ,UPPER(opd.e_pickup_state) e_pickup_state ,UPPER(opd.e_pickup_country) e_pickup_country ,opd.e_pickup_pin_code ,CAST(oa.appointment_date AS TIMESTAMP) appointment_date ,UPPER(wm.\"Mapped Warehouse Name\") \"Mapped Warehouse Name\" ,UPPER(wm.\"Client Name\") \"Client Name\" from public.Quickshift_shipping_qs_order o left join( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY fr_order_id ORDER BY CASE WHEN pickup_date IS NOT NULL OR pickup_schedule_date IS NOT NULL THEN 1 